import React from 'react';

export default function OverdueQueue({
  reminders,
  bdName,
  onOpenFollowUp,
  onSimulatePayment,
  onCancelLink,
  formatOverdueTime
}) {
  return (
    <div>
      <div className="page-title-banner">
        <div>
          <h1 className="page-heading">Overdue SLA Follow-up Queue</h1>
          <p className="page-subheading">
            Candidate payment links assigned to <strong>{bdName || 'BD'}</strong> that have breached the 24-hour SLA window.
          </p>
        </div>
      </div>

      <div className="main-card">
        <div className="card-header-bar">
          <div className="card-header-title">
            <span>🚨 Overdue Attention List</span>
            {reminders.length > 0 && (
              <span className="chip critical">{reminders.length} Overdue</span>
            )}
          </div>
          <span style={{ fontSize: '12px', color: '#64748b' }}>
            Follow-up required within today
          </span>
        </div>

        {reminders.length === 0 ? (
          <div className="empty-box">
            <div className="empty-icon-lg">🎉</div>
            <h3 style={{ color: '#0f172a', fontWeight: 700 }}>Zero Overdue Reminders!</h3>
            <p style={{ marginTop: '4px' }}>All payment links assigned to you are either paid or within their 24-hour SLA window.</p>
          </div>
        ) : (
          <table className="enterprise-table">
            <thead>
              <tr>
                <th>Candidate / Lead</th>
                <th>Target Course</th>
                <th>Token Amount</th>
                <th>SLA Aging</th>
                <th>Follow-up Notes</th>
                <th>Quick Actions</th>
              </tr>
            </thead>
            <tbody>
              {reminders.map((rem) => (
                <tr key={rem.id}>
                  <td>
                    <div className="lead-user-cell">
                      <div className="lead-avatar">
                        {rem.lead_name?.slice(0, 2).toUpperCase() || 'LD'}
                      </div>
                      <div>
                        <div className="lead-primary-text">{rem.lead_name}</div>
                        <div className="lead-sub-text">📞 {rem.lead_phone}</div>
                      </div>
                    </div>
                  </td>
                  <td>
                    <span style={{ fontWeight: 600, color: '#334155' }}>{rem.course_title}</span>
                  </td>
                  <td>
                    <strong style={{ fontSize: '14px', color: '#0f172a' }}>
                      ₹{rem.amount?.toLocaleString()}
                    </strong>
                  </td>
                  <td>
                    <span className="chip critical">
                      ⏱️ {formatOverdueTime(rem.overdue_duration_seconds)}
                    </span>
                  </td>
                  <td>
                    <span className="chip neutral">
                      📝 {rem.follow_up_count} Touchpoint{rem.follow_up_count === 1 ? '' : 's'}
                    </span>
                  </td>
                  <td>
                    <div style={{ display: 'flex', gap: '8px' }}>
                      <button
                        className="btn btn-primary btn-sm"
                        onClick={() => onOpenFollowUp(rem)}
                      >
                        📝 Log Call Note
                      </button>
                      <button
                        className="btn btn-success btn-sm"
                        title="Simulate student paying via Gateway Webhook"
                        onClick={() => onSimulatePayment(rem.payment_link_id)}
                      >
                        ⚡ Simulate Paid
                      </button>
                      <button
                        className="btn btn-danger-outline btn-sm"
                        onClick={() => onCancelLink(rem.payment_link_id)}
                      >
                        Cancel
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
