import React from 'react';

export default function LeadsTable({
  leads,
  courses,
  onOpenAddLeadModal,
  onSelectLeadForLink
}) {
  return (
    <div>
      <div className="page-title-banner">
        <div>
          <h1 className="page-heading">Assigned Leads Directory</h1>
          <p className="page-subheading">Candidate pipeline assigned to the active BD for course enrollment.</p>
        </div>
        <div className="banner-action-group">
          <button className="btn btn-primary" onClick={onOpenAddLeadModal}>
            ➕ Add New Lead
          </button>
        </div>
      </div>

      <div className="main-card">
        {leads.length === 0 ? (
          <div className="empty-box">
            <div className="empty-icon-lg">👥</div>
            <h3 style={{ color: '#0f172a', fontWeight: 700 }}>No Leads Assigned</h3>
            <p>Create a new lead to start the enrollment process.</p>
          </div>
        ) : (
          <table className="enterprise-table">
            <thead>
              <tr>
                <th>Candidate Name</th>
                <th>Contact</th>
                <th>Interested Course</th>
                <th>Status</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {leads.map((lead) => {
                const course = courses.find((c) => c.id === lead.course_id);
                return (
                  <tr key={lead.id}>
                    <td>
                      <div className="lead-user-cell">
                        <div className="lead-avatar">
                          {lead.name?.slice(0, 2).toUpperCase() || 'LD'}
                        </div>
                        <div>
                          <div className="lead-primary-text">{lead.name}</div>
                          <div className="lead-sub-text">{lead.city || 'Student'}</div>
                        </div>
                      </div>
                    </td>
                    <td>
                      <div>📞 {lead.phone}</div>
                      <div style={{ fontSize: '11px', color: '#64748b' }}>{lead.email || '-'}</div>
                    </td>
                    <td>
                      <span style={{ fontWeight: 600, color: '#334155' }}>
                        {course ? course.title : lead.course_id}
                      </span>
                    </td>
                    <td>
                      <span className={`chip ${lead.status === 'CONVERTED' ? 'success' : lead.status === 'PAYMENT_LINK_SENT' ? 'warning' : 'neutral'}`}>
                        {lead.status}
                      </span>
                    </td>
                    <td>
                      <button
                        className="btn btn-secondary btn-sm"
                        onClick={() => onSelectLeadForLink(lead, course)}
                      >
                        💳 Send Payment Link
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}
